css:
:where(.wtyg-map-site_rodeo){--earth-dark: #2d3436;
            --earth-brown: #6c5448;
            --earth-sand: #d4a574;
            --earth-sage: #8b9474;
            --earth-sky: #7c9eb2;
            --accent-warm: #c9896b;
            --text-light: #f5f5f0;
            --text-dark: #2d2d2d;}
:where(.wtyg-map-site_rodeo) *{margin: 0;
            padding: 0;
            box-sizing: border-box;}
:where(.wtyg-map-site_rodeo){font-family: 'Work Sans', sans-serif;
            background: var(--earth-dark);
            color: var(--text-light);
            overflow: hidden;}
:where(.wtyg-map-site_rodeo) :is([data-wtyg-id="map"],#wtyg-noid-map){width: 100vw;
            height: 100vh;
            position: relative;}
:where(.wtyg-map-site_rodeo) .map-overlay{position: absolute;
            top: 0;
            left: 0;
            right: 0;
            z-index: 1000;
            background: linear-gradient(180deg, rgba(45,52,54,0.95) 0%, rgba(45,52,54,0.7) 70%, transparent 100%);
            padding: 2rem 3rem 4rem;
            pointer-events: none;}
:where(.wtyg-map-site_rodeo) .header{display: flex;
            justify-content: space-between;
            align-items: flex-start;
            gap: 2rem;}
:where(.wtyg-map-site_rodeo) .title-section h1{font-family: 'Cormorant Garamond', serif;
            font-size: 3rem;
            font-weight: 300;
            letter-spacing: 0.02em;
            margin-bottom: 0.5rem;
            color: var(--text-light);
            opacity: 0;
            animation: fadeInUp 0.8s ease forwards;}
:where(.wtyg-map-site_rodeo) .title-section p{font-size: 0.95rem;
            color: var(--earth-sand);
            letter-spacing: 0.05em;
            text-transform: uppercase;
            font-weight: 300;
            opacity: 0;
            animation: fadeInUp 0.8s ease 0.2s forwards;}
:where(.wtyg-map-site_rodeo) .filter-panel{pointer-events: auto;
            display: flex;
            gap: 0.75rem;
            flex-wrap: wrap;
            opacity: 0;
            animation: fadeInUp 0.8s ease 0.4s forwards;}
:where(.wtyg-map-site_rodeo) .filter-btn{background: rgba(255,255,255,0.08);
            border: 1px solid rgba(255,255,255,0.15);
            color: var(--text-light);
            padding: 0.6rem 1.2rem;
            border-radius: 2rem;
            font-family: 'Work Sans', sans-serif;
            font-size: 0.85rem;
            font-weight: 400;
            cursor: pointer;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            backdrop-filter: blur(10px);
            letter-spacing: 0.02em;}
:where(.wtyg-map-site_rodeo) .filter-btn:hover{background: rgba(255,255,255,0.15);
            border-color: var(--earth-sand);
            transform: translateY(-2px);}
:where(.wtyg-map-site_rodeo) .filter-btn.active{background: var(--earth-sand);
            border-color: var(--earth-sand);
            color: var(--earth-dark);
            font-weight: 500;}
:where(.wtyg-map-site_rodeo) .stats-panel{position: absolute;
            bottom: 2rem;
            left: 3rem;
            z-index: 1000;
            background: rgba(45,52,54,0.9);
            backdrop-filter: blur(20px);
            border: 1px solid rgba(255,255,255,0.1);
            border-radius: 1rem;
            padding: 1.5rem 2rem;
            pointer-events: none;
            opacity: 0;
            animation: fadeInUp 0.8s ease 0.6s forwards;}
:where(.wtyg-map-site_rodeo) .stat-item{display: flex;
            align-items: baseline;
            gap: 0.5rem;
            margin-bottom: 0.5rem;}
:where(.wtyg-map-site_rodeo) .stat-item:last-child{margin-bottom: 0;}
:where(.wtyg-map-site_rodeo) .stat-number{font-family: 'Cormorant Garamond', serif;
            font-size: 2rem;
            font-weight: 600;
            color: var(--earth-sand);}
:where(.wtyg-map-site_rodeo) .stat-label{font-size: 0.85rem;
            color: var(--text-light);
            opacity: 0.8;
            text-transform: uppercase;
            letter-spacing: 0.05em;}
@keyframes fadeInUp{
            from {
                opacity: 0;
                transform: translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }
:where(.wtyg-map-site_rodeo) .leaflet-popup-content-wrapper{background: rgba(45,52,54,0.98);
            backdrop-filter: blur(20px);
            border: 1px solid rgba(255,255,255,0.15);
            border-radius: 1rem;
            padding: 0;
            box-shadow: 0 20px 60px rgba(0,0,0,0.3);}
:where(.wtyg-map-site_rodeo) .leaflet-popup-content{margin: 0;
            min-width: 250px;}
:where(.wtyg-map-site_rodeo) .leaflet-popup-tip{background: rgba(45,52,54,0.98);
            border: 1px solid rgba(255,255,255,0.15);
            border-top: none;
            border-right: none;}
:where(.wtyg-map-site_rodeo) .popup-content{padding: 1.5rem;}
:where(.wtyg-map-site_rodeo) .popup-category{display: inline-block;
            background: var(--earth-sand);
            color: var(--earth-dark);
            padding: 0.3rem 0.8rem;
            border-radius: 1rem;
            font-size: 0.7rem;
            font-weight: 500;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-bottom: 0.75rem;}
:where(.wtyg-map-site_rodeo) .popup-name{font-family: 'Cormorant Garamond', serif;
            font-size: 1.3rem;
            font-weight: 600;
            color: var(--text-light);
            margin-bottom: 0.5rem;
            line-height: 1.3;}
:where(.wtyg-map-site_rodeo) .popup-address{font-size: 0.9rem;
            color: var(--earth-sand);
            margin-bottom: 0.25rem;
            opacity: 0.9;}
:where(.wtyg-map-site_rodeo) .popup-country{font-size: 0.85rem;
            color: var(--text-light);
            opacity: 0.7;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-top: 0.5rem;}
:where(.wtyg-map-site_rodeo) .marker-icon{border-radius: 50%;
            border: 2px solid rgba(255,255,255,0.3);
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.3s ease;
            cursor: pointer;}
:where(.wtyg-map-site_rodeo) .marker-icon:hover{transform: scale(1.2);
            border-width: 3px;}
:where(.wtyg-map-site_rodeo) .marker-rodeo{background: rgba(212, 165, 116, 0.9);}
:where(.wtyg-map-site_rodeo) .marker-charreada{background: rgba(201, 137, 107, 0.9);}
:where(.wtyg-map-site_rodeo) .marker-coleo{background: rgba(139, 148, 116, 0.9);}
:where(.wtyg-map-site_rodeo) .marker-rodeio{background: rgba(124, 158, 178, 0.9);}
:where(.wtyg-map-site_rodeo) .marker-other{background: rgba(108, 84, 72, 0.9);}
@media (max-width: 768px){:where(.wtyg-map-site_rodeo) .title-section h1{font-size: 2rem;}
:where(.wtyg-map-site_rodeo) .map-overlay{padding: 1.5rem;}
:where(.wtyg-map-site_rodeo) .stats-panel{left: 1.5rem;
                bottom: 1.5rem;
                padding: 1rem 1.5rem;}
:where(.wtyg-map-site_rodeo) .filter-panel{gap: 0.5rem;}
:where(.wtyg-map-site_rodeo) .filter-btn{padding: 0.5rem 1rem;
                font-size: 0.8rem;}}
